from lib import *
S = SS('w87')
steps = [
    step("升级握手:一个普通的 HTTP/1.1 GET 请求,带 Upgrade: websocket、Connection: Upgrade、Sec-WebSocket-Version: 13 和一个随机的 Sec-WebSocket-Key(16 字节随机数的 base64)。服务器回 101 Switching Protocols,并给出 Sec-WebSocket-Accept——它是 base64(SHA-1(Key + \"258EAFA5-E914-47DA-95CA-C5AB0DC85B11\")),我自己算出来 UVpqiCGPdLKx3UxuR7NIgKcZLTw=,与服务器给的完全一致。这个值只证明服务器真的听懂了 WebSocket 握手(防止普通 HTTP 服务器被误当成 WebSocket 服务器),不是安全措施。101 之后同一条 TCP 连接不再说 HTTP,双方改用 WebSocket 帧。", t=tl(S(1)), mark=lidx(S(1), 'Upgrade: websocket', 'HTTP/1.1 101'), done=lidx(S(1), 'Accept 的计算', '101 之后同一条 TCP'), kv=KV([['请求', 'GET + Upgrade: websocket + Sec-WebSocket-Key'], ['响应', '101 Switching Protocols + Sec-WebSocket-Accept'], ['Accept', 'base64(SHA-1(Key + GUID)),我自己算的一致']], ['响应'])),
    step("帧的格式。发一个文本消息 \"Hello\":客户端→服务器的帧 11 字节 81 85 37 fa 21 3d 7f 9f 4d 51 58。81 = FIN 位 1 + 操作码 1(文本);85 = 掩码位 1 + 长度 5;37 fa 21 3d 是 4 字节掩码密钥;后面 5 字节是载荷与密钥循环异或的结果——逐字节验证:7f^37=48(H)、9f^fa=65(e)、4d^21=6c(l)、51^3d=6c(l)、58^37=6f(o)。客户端发出的帧必须掩码。服务器→客户端的回显帧 7 字节 81 05 48 65 6c 6c 6f:没有掩码位、没有密钥,头部只有 2 字节。所以 5 字节的消息,客户端方向开销 6 字节,服务器方向开销 2 字节。", t=tl(S(2)), mark=lidx(S(2), '客户端→服务器 帧', '验证'), done=lidx(S(2), '服务器→客户端 帧', '所以 5 字节的消息'), b=bars([['客户端帧头', 6, '6 字节'], ['服务器帧头', 2, '2 字节']], 6, mark=[0], done=[1]), kv=KV([['客户端帧', '81 85 | 掩码密钥 4 字节 | 异或后的载荷'], ['服务器帧', '81 05 | 载荷(无掩码)'], ['开销', '客户端 6 字节 / 服务器 2 字节']], ['客户端帧'])),
    step("长度的三种编码。载荷 125 字节:长度放在第二个字节的低 7 位里,客户端帧头 6 字节(2 + 4 掩码),服务器帧头 2 字节;载荷 126 字节:第二个字节写 126,后面跟 2 字节的真实长度,客户端帧头 8 字节,服务器 4 字节;载荷 65535 字节:仍是 126 + 2 字节;载荷 65536 字节:第二个字节写 127,后面跟 8 字节的长度,客户端帧头 14 字节,服务器 10 字节。四个消息服务器都原样回显。大消息的帧头开销占比可以忽略,小消息的开销主要是那 2~6 字节。", t=tl(S(3)), mark=lidx(S(3), '载荷    126', '载荷  65536'), done=lidx(S(3), '载荷    125', '载荷  65535'), b=bars([['≤125 字节(服务器)', 2, '2 字节'], ['126~65535(服务器)', 4, '4 字节'], ['≥65536(服务器)', 10, '10 字节'], ['≥65536(客户端)', 14, '14 字节']], 14, mark=[2, 3], done=[0, 1]), kv=KV([['≤ 125', '7 位长度,头 2 字节(客户端 6)'], ['126~65535', '126 + 2 字节,头 4 字节(客户端 8)'], ['≥ 65536', '127 + 8 字节,头 10 字节(客户端 14)']], ['≥ 65536'])),
    step("分片与控制帧。把一个消息拆成 3 个帧:一个 FIN=0 的文本帧 \"frag-\"、一个 FIN=0 的继续帧 \"ment-\"、一个 FIN=1 的继续帧 \"end\";在第一和第二个分片之间插一个 ping(载荷 PING1)。服务器先回 pong(载荷 PING1 原样返回),分片消息收齐之后回显完整的文本消息 \"frag-ment-end\"。规则:控制帧(ping、pong、close)可以夹在一个数据消息的分片之间,但不能夹别的数据消息。", t=tl(S(4)), mark=lidx(S(4), '服务器回来的帧'), done=lidx(S(4), '分片之间可以夹控制帧'), kv=KV([['分片', '文本帧 FIN=0 + 继续帧 + 继续帧 FIN=1'], ['ping', '夹在分片之间,服务器先回 pong'], ['回显', '收齐后一个完整文本消息']], ['ping'])),
    step("协议违规:客户端发了一个没有掩码的帧。规范要求服务器关闭连接并给出 1002(协议错误)。实测服务器回了一个关闭帧,码 1002,原因 \"incorrect masking\"。掩码的目的不是加密(密钥就在帧里),而是防止客户端里的恶意脚本构造出能骗过中间代理缓存的“看起来像 HTTP”的字节序列。", t=tl(S(5)), mark=lidx(S(5), '服务器回 关闭 帧'), done=lidx(S(5), '服务器回 关闭 帧'), kv=KV([['未掩码的客户端帧', '服务器回 Close,码 1002'], ['原因文字', '"incorrect masking"']], ['未掩码的客户端帧'])),
    step("正常关闭。客户端发 Close 帧:88 85 37 fa 21 3d 34 12 43 44 52(88 = FIN + 操作码 8;载荷是码 1000 加原因 \"bye\",经过掩码)。服务器回一个 Close 帧,载荷 03 e8 62 79 65(03 e8 = 1000,后面 \"bye\"),然后 TCP 连接才被关闭(之后读到的是连接关闭)。关闭是一次两个方向的握手:谁先发 Close 谁就在等对方的 Close。", t=tl(S(6)), mark=lidx(S(6), '客户端→服务器 Close 帧', '服务器→客户端:关闭'), done=lidx(S(6), '客户端→服务器 Close 帧'), kv=KV([['客户端', 'Close 帧,码 1000,原因 bye'], ['服务器', '回 Close 帧,码 1000'], ['之后', 'TCP 连接关闭']], ['服务器'])),
]
A = mkartw('w87', 87, '网络协议,HTTP,WebSocket,升级握手,帧,掩码,ping,关闭,真实验证,动画演示',
    '手工收发 WebSocket 帧:101 握手的 Sec-WebSocket-Accept 我自己算出来一致;"Hello" 的客户端帧 11 字节(2 + 4 掩码 + 5)、服务器帧 7 字节;长度的 7 位 / 16 位 / 64 位三种编码对应 2 / 4 / 10 字节帧头;分片之间夹 ping;未掩码帧得到 1002;关闭握手。',
    'WebSocket 从一次普通的 HTTP 请求开始,升级之后在同一条 TCP 连接上变成全双工的二进制帧。这篇不借助 WebSocket 客户端库,用套接字手工完成握手、拼帧、读帧,逐字节验证掩码、长度编码、分片、控制帧和关闭握手。',
    [('UVpqiCGPdLKx3UxuR7NIgKcZLTw=', '我自己用 SHA-1 + base64 算出的 Sec-WebSocket-Accept,与服务器给的一致'), ('6 字节 vs 2 字节', '客户端与服务器方向每个小消息的帧头开销(客户端多 4 字节掩码)'), ('1002', '客户端发出未掩码帧时服务器回的关闭码')],
    [('升级握手', '<p>HTTP/1.1 GET + Upgrade;Accept = base64(SHA-1(Key + 固定 GUID)),只证明服务器懂 WebSocket。</p>'),
     ('帧格式', '<p>FIN + 操作码 + 掩码位 + 长度;客户端帧必须掩码(4 字节密钥异或),服务器帧不掩码。</p>'),
     ('长度编码', '<p>≤125 用 7 位,126~65535 用 126+2 字节,更大用 127+8 字节。</p>'),
     ('分片与控制帧', '<p>消息可拆成多帧,控制帧可以夹在分片之间。</p>'),
     ('未掩码的帧', '<p>客户端发未掩码帧,服务器回 Close 码 1002(incorrect masking)。</p>'),
     ('关闭握手', '<p>Close 帧(码 1000)一来一回,然后 TCP 才关闭。</p>')],
    steps,
    [ENV_W + '。服务器是 Python 的 websockets 17.2 库写的回显服务(关闭压缩和自动 ping),监听 lo0 上的 9400~9499 端口;客户端的握手和帧都是手工拼的,没有用 WebSocket 客户端库;没有测公网的 WebSocket 服务',
     '没有验证:permessage-deflate 压缩扩展;wss(TLS 之上的 WebSocket);子协议(Sec-WebSocket-Protocol);服务器主动 ping 与超时;代理 / 负载均衡对 WebSocket 空闲连接的超时;浏览器里的 WebSocket API 行为;Origin 头校验(跨站 WebSocket 劫持)'],
    'WebSocket')
